    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    fg = next((x for row in grid for x in row if x != bg), bg)
    out = [row[:] for row in grid]

    # Fill background runs bounded by foreground cells in either direction.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                start = c
                while c < w and grid[r][c] == bg:
                    c += 1
                if start > 0 and c < w and grid[r][start - 1] == fg and grid[r][c] == fg:
                    for j in range(start, c):
                        out[r][j] = 2
            else:
                c += 1

