def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and grid[r][c] == bg:
                out[r][c] = 2
    return out
